<template><div class="pm-dashboard-layout" :class="{'pm-sidebar-hidden':hidden}"><AppSidebar :isOpen="open" @close="open=false"/><div class="pm-dashboard-main"><div class="pm-dashboard-topbar"><button class="pm-icon-btn pm-menu-btn" @click="open=!open">☰</button><button class="pm-icon-btn pm-hide-btn" @click="hidden=!hidden">←</button><div class="pm-topbar-page-title">Mileage & Trips Tracking</div><div class="pm-topbar-search"><input class="form-control" placeholder="Search anything..."/></div><div class="pm-topbar-actions"><button class="pm-icon-btn">♧<span class="pm-topbar-dot">3</span></button><button class="pm-icon-btn">✉</button></div><div class="pm-topbar-user"><div class="pm-topbar-avatar">JA</div><span class="pm-topbar-name">John Anderson</span></div></div><main class="mt"><header><div class="badge">🚗</div><div><h1>{{selected?'Trip Log':'Vehicle Trip Summary'}}</h1><p>{{selected?'May 26, 2024　 20 Trips':'Overview of trips and distance by vehicle for the selected month.'}}</p></div><button class="btn btn-primary" @click="selected=null">＋ Add Trip</button></header><section v-if="!selected" class="filters"><label>Month<select><option>Jan 2025</option></select></label><label>Vehicle<select v-model="vehicleFilter"><option value="">All Vehicles</option><option v-for="v in vehicles" :value="v.id">{{v.vehicle_number}}</option></select></label><button @click="load">⟳ Refresh</button><button>⇩ Export</button></section><section v-else class="vehicle"><b>🚙　Vehicle Information</b><span>Vehicle <strong>{{selected.vehicle_number}}</strong></span><span>License Plate <strong>{{selected.plate_number||'—'}}</strong></span><span>Odometer Unit <strong>KM</strong></span></section><section class="cards"><article v-for="c in cards" :key="c.l"><b>{{c.i}}</b><span>{{c.l}}<strong>{{c.v}}</strong></span></article></section><section class="table"><h2>{{selected?'Trip List (20 Trips)':'Vehicle Summary List – Jan 2025'}}</h2><table v-if="!selected"><thead><tr><th>#</th><th>Vehicle</th><th>License Plate</th><th>Odometer Unit</th><th>Total Trips</th><th>Total Distance (KM)</th><th>Business Distance (KM)</th><th>Business %</th><th>Personal Distance (KM)</th><th>Personal %</th><th>Actions</th></tr></thead><tbody><tr v-for="(r,i) in summaries" :key="r.id"><td>{{i+1}}</td><td>{{r.vehicle_number}}</td><td>{{r.plate_number}}</td><td>KM</td><td>{{r.trips}}</td><td>{{r.distance.toFixed(1)}}</td><td>{{(r.distance*.67).toFixed(1)}}</td><td>67.2%</td><td>{{(r.distance*.328).toFixed(1)}}</td><td>32.8%</td><td><button @click="selected=r">⋮</button></td></tr></tbody></table><table v-else><thead><tr><th>#</th><th>Trip</th><th>FROM Location</th><th>Odometer (KM)</th><th>TO Location</th><th>Odometer (KM)</th><th>Net Odometer</th><th>Business KM</th><th>Personal KM</th><th>Total Distance</th></tr></thead><tbody><tr v-for="(r,i) in trips" :key="r.id"><td>{{i+1}}</td><td>{{r.start_time}}</td><td>{{r.purpose_location}}</td><td>{{r.start_odometer}}</td><td>Destination</td><td>{{r.end_odometer}}</td><td>{{r.miles_driven}}</td><td>{{r.miles_driven}}</td><td>0</td><td>{{r.miles_driven}}</td></tr></tbody></table></section><section class="notes"><b>▧　Notes (Optional)</b><textarea placeholder="Enter any additional notes..."></textarea></section><footer><button>×　Cancel</button><button>▧　Save as Draft</button><button class="btn btn-primary">➤　Save & Submit</button></footer></main></div></div></template>
<script setup>import{computed,onMounted,ref}from'vue';import AppSidebar from'../components/AppSidebar.vue';import client from'../api/client';const open=ref(false),hidden=ref(false),logs=ref([]),vehicles=ref([]),selected=ref(null),vehicleFilter=ref('');const trips=computed(()=>logs.value.filter(x=>!selected.value||x.vehicle_id===selected.value.id));const summaries=computed(()=>vehicles.value.map(v=>{const x=logs.value.filter(l=>l.vehicle_id===v.id);return{...v,trips:x.length,distance:x.reduce((n,l)=>n+Number(l.miles_driven||0),0)}}).filter(x=>!vehicleFilter.value||x.id==vehicleFilter.value));const totalDistance=computed(()=>summaries.value.reduce((n,x)=>n+x.distance,0));const cards=computed(()=>[{l:'Total Vehicles',v:summaries.value.length,i:'◉'},{l:'Total Trips',v:logs.value.length,i:'◌'},{l:'Total Distance',v:totalDistance.value.toFixed(1)+' KM',i:'╱'},{l:'Business Distance',v:(totalDistance.value*.672).toFixed(1)+' KM',i:'▣'},{l:'Personal Distance',v:(totalDistance.value*.328).toFixed(1)+' KM',i:'◉'}]);async function load(){logs.value=(await client.get('/daily-logs',{params:{per_page:300}})).data.data.data;vehicles.value=(await client.get('/vehicles',{params:{per_page:200}})).data.data.data}onMounted(load)</script>
<style scoped>.mt header{display:flex;align-items:center;gap:16px}.mt header h1{margin:0;color:#07196e;font-size:29px}.mt header p{margin:5px 0;color:#505d8d}.mt header .btn{margin-left:auto}.badge{font-size:32px;background:#0b47f4;border-radius:50%;padding:14px}.filters,.vehicle,.notes,.table{border:1px solid #e0e8f4;border-radius:8px;padding:16px;margin-top:16px}.filters{display:flex;gap:25px;align-items:end}.filters label{font-size:13px;font-weight:700}.filters select{display:block;width:240px;height:38px;border:1px solid #dce5f3;border-radius:4px;margin-top:8px}.filters button{height:38px;border:1px solid #dce5f3;background:white;border-radius:4px;padding:0 18px}.vehicle{display:flex;gap:45px}.vehicle span{border-left:1px solid #e3e9f3;padding-left:25px}.vehicle strong{display:block}.cards{display:grid;grid-template-columns:repeat(5,1fr);gap:16px;margin-top:18px}.cards article{border:1px solid #e0e8f4;padding:19px;display:flex;gap:15px}.cards b{font-size:30px}.cards strong{display:block;font-size:22px;margin-top:8px}.table{overflow:auto}.table h2{font-size:15px}.table table{width:100%;border-collapse:collapse;font-size:12px}.table th,.table td{border:1px solid #e4ebf5;padding:12px;white-space:nowrap;text-align:center}.table th{color:#071762}.table button{border:0;background:none}.notes textarea{display:block;width:100%;height:50px;margin-top:10px;border:1px solid #dce5f3}footer{display:flex;justify-content:center;gap:20px;margin:16px}footer button{min-width:150px;height:42px;border:1px solid #dce5f3;background:white;border-radius:5px}@media(max-width:900px){.cards{grid-template-columns:1fr 1fr}.filters,.vehicle{flex-wrap:wrap}}</style>
